cd /dateutil && python -c "
import datetime, random
from dateutil.relativedelta import relativedelta as rd
random.seed(1)
bad=[]
fields=['days','hours','minutes','seconds','microseconds']
for _ in range(50000):
    dt = datetime.datetime(2000,1,1)+datetime.timedelta(days=random.uniform(0,3000), seconds=random.uniform(0,86400))
    kw={}
    for f in fields:
        if random.random()<0.5:
            kw[f]=random.uniform(-100,100)
    r=rd(**kw)
    got = dt + r
    exp = dt + r.normalized()
    if got != exp:
        bad.append((kw,got,exp))
print('add vs normalized mismatches:', len(bad))
for b in bad[:10]: print(b)
